import java.util.*;

class Solution {
  public int longestSubarray(int[] nums, int k) {
    int n = nums.length;
    // first and last prefix index (0..n) for each prefix-sum residue
    int[] first = new int[k], last = new int[k];
    Arrays.fill(first, -1);
    Arrays.fill(last, -1);
    int prefix = 0;
    for (int j = 0; j <= n; j++) {
      if (j > 0) prefix = Math.floorMod(prefix + nums[j - 1], k);
      if (first[prefix] < 0) first[prefix] = j;
      last[prefix] = j;
    }
    int best = 0;
    for (int t = 0; t < k; t++) if (first[t] >= 0) best = Math.max(best, last[t] - first[t]);

    // negating x lowers the sum by 2x, so group positions by (2x mod k)
    int[] count = new int[k];
    for (int x : nums) count[Math.floorMod(2 * x, k)]++;
    int[][] positions = new int[k][];
    for (int c = 0; c < k; c++) positions[c] = new int[count[c]];
    int[] fill = new int[k];
    for (int i = 0; i < n; i++) {
      int c = Math.floorMod(2 * nums[i], k);
      positions[c][fill[c]++] = i;
    }
    // for residue c and start residue t only the widest span matters: if it holds no element of class c,
    // no shorter span inside it does either
    for (int c = 0; c < k; c++) {
      int[] pos = positions[c];
      if (pos.length == 0) continue;
      for (int t = 0; t < k; t++) {
        int from = first[t];
        if (from < 0) continue;
        int to = last[(t + c) % k];
        if (to - from <= best) continue;
        int q = lowerBound(pos, from);
        if (q < pos.length && pos[q] <= to - 1) best = to - from;
      }
    }
    return best;
  }

  private int lowerBound(int[] a, int key) {
    int lo = 0, hi = a.length;
    while (lo < hi) {
      int m = (lo + hi) >>> 1;
      if (a[m] < key) lo = m + 1;
      else hi = m;
    }
    return lo;
  }
}
